{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "notebook",
        "category": "notebooks",
        "max_price": 1595990,
        "attributes": {
          "peso_kg": {
            "max": 1.3
          }
        }
      }
    },
    {
      "id": "s2",
